INSERT INTO `patient_histories` (`id`, `patient_id`, `main_symptoms`, `physical_symptoms`, `sleep_problems`, `dream_problems`, `worship_problems`, `family_history`, `financial_family_situation`, `previous_medical_history`, `duration_of_problems`, `additional_information`, `recorded_by`, `created_at`, `updated_at`, `problem_duration`, `previous_treatment_history`, `rizq_family_situation`, `genetic_history`) VALUES (1, 'RSCC-P-1001', '["Chest heaviness & suffocation","Sudden unprovoked anger","Constant exhaustion"]', '["Upper back stiffness","Stomach tingling sensation","Tension headache"]', '["Insomnia","Frequent sudden awakenings","Sleep paralysis (Kaboos)"]', '["Black dogs chasing","Falling from high structures","Graveyards"]', '["Intrusive doubts (Waswas) during Wudu","Sudden heavy yawning during Adhan"]', 'No hereditary mental illness. Happy family background.', 'Experienced sudden unexplained loss in wholesale textile business 7 months ago.', 'Visited cardiologist and neurologist at Feni General Hospital; ECG, Echo and Brain MRI all reported completely normal.', '6 to 12 months', 'Patient previously given an amulet (taweez) by a village healer which was subsequently removed and burned according to Sunnah.', 'Muhammadullah Miah', '2026-11-18 08:12:08', '2026-11-18 08:12:08', '6 to 12 months', NULL, 'Experienced sudden unexplained loss in wholesale textile business 7 months ago.', NULL);
