INSERT INTO `patient_histories` (`id`, `patient_id`, `main_symptoms`, `physical_symptoms`, `sleep_problems`, `dream_problems`, `worship_problems`, `family_history`, `financial_family_situation`, `previous_medical_history`, `duration_of_problems`, `additional_information`, `recorded_by`, `created_at`, `updated_at`, `problem_duration`, `previous_treatment_history`, `rizq_family_situation`, `genetic_history`) VALUES (52, 'RSCC-P-1119', '["বুকে চাপ ও দম বন্ধ হওয়ার অনুভূতি","হঠাৎ অহেতুক তীব্র রাগ ও ক্ষোভ","সার্বক্ষণিক অব্যক্ত ক্লান্তি ও দুর্বলতা","পরিবার ও আত্মীয়দের প্রতি হঠাৎ অনীহা","সামাজিক মেলামেশায় তীব্র অনীহা ও একাকিত্ব","অকারণে বারবার কান্না পাওয়া","স্মৃতিভ্রম ও মনোযোগের অভাব"]', '["পেটে জ্বালাপোড়া বা সূঁচ ফোটানোর অনুভূতি","পিঠের উপরিভাগ ও ঘাড়-কাঁধে প্রচণ্ড ভার","ওষুধে না কমা দীর্ঘস্থায়ী মাথাব্যথা","হাত-পায়ে অবশ বা ঝিঁঝিঁ লাগা","হঠাৎ শরীরে তীব্র ঠান্ডা বা গরম লাগা","পেট ফাঁপা ও দীর্ঘস্থায়ী বদহজম"]', '["তীব্র অনিদ্রা ও ঘুমাতে দীর্ঘ সময় লাগা","বোবা ধরা / স্লিপ প্যারালাইসিস","ভয়ে বারবার ঘুম ভেঙে যাওয়া","ঘুমের মধ্যে দাঁত কিড়মিড় করা","অতিরিক্ত তন্দ্রাভাব ও ফজর পড়তে কষ্ট"]', '["কালো কুকুর, বিড়াল বা হিংস্র প্রাণীর আক্রমণ","সাপ বা বিচ্ছুর তাড়া করা","উঁচু স্থান থেকে নিচে পড়ে যাওয়া","কবরস্থান বা নোংরা স্থানে ঘুরে বেড়ানো","ভয়ংকর ছায়ামূর্তি দেখা","ঘোলা পানিতে ডুবে যাওয়া"]', '["আযান বা কুরআন তিলাওয়াত শুনতে অস্বস্তি","অজু বা সালাতে তীব্র ওয়াসওয়াসা ও সন্দেহ","তিলাওয়াতের সময় অতিরিক্ত হাই ও ঘুম আসা","সূরা বাক্বারাহ শুনলে বুক ধড়ফড় করা","নিয়মিত সালাত ও যিকিরে অনীহা"]', 'মা আক্রান্ত', 'সন্দেহ করা', 'অন্যান্য চিকিৎসা:', '৫ বছরের বেশি', 'হয়েছে', 'Muhammadullah Miah', '2026-11-19 13:36:15', '2026-11-19 13:36:15', NULL, NULL, NULL, NULL);
INSERT INTO `patient_histories` (`id`, `patient_id`, `main_symptoms`, `physical_symptoms`, `sleep_problems`, `dream_problems`, `worship_problems`, `family_history`, `financial_family_situation`, `previous_medical_history`, `duration_of_problems`, `additional_information`, `recorded_by`, `created_at`, `updated_at`, `problem_duration`, `previous_treatment_history`, `rizq_family_situation`, `genetic_history`) VALUES (59, 'RSCC-P-1156', '["Chest heaviness & suffocation","Sudden unprovoked anger","Constant unexplained exhaustion"]', '["Stomach tingling / burning sensation","Upper back & shoulder tension"]', '["Severe insomnia","Sleep paralysis (Kaboos)","Frequent abrupt awakenings"]', '["Black dogs and beasts attacking","Falling from high structures","Walking in graveyards"]', '["Severe intrusive doubts (Waswas) in Wudu / Salah","Sudden overwhelming sleepiness during recitation"]', 'পরিবারে কোনো পূর্ববর্তী মানসিক বা জিনঘটিত রোগের ইতিহাস নেই।', 'ব্যবসায় হঠাৎ অচলাবস্থা সৃষ্টি হয়েছে।', 'কবিরাজ: ৩টি তাবিয দেওয়া হয়েছিল। এলোপ্যাথিক: ঘুমের ওষুধ খেয়েছিলেন।', '২ বছর', 'Patient wore a copper talisman from village astrologer which was removed.', 'Muhammadullah Miah', '2026-11-20 05:49:52', '2026-11-20 05:49:52', '২ বছর', 'কবিরাজ: ৩টি তাবিয দেওয়া হয়েছিল। এলোপ্যাথিক: ঘুমের ওষুধ খেয়েছিলেন।', 'ব্যবসায় হঠাৎ অচলাবস্থা সৃষ্টি হয়েছে।', 'পরিবারে কোনো পূর্ববর্তী মানসিক বা জিনঘটিত রোগের ইতিহাস নেই।');
INSERT INTO `diagnosis_categories` (`id`, `code`, `name_bn`, `name_en`, `description_bn`, `description_en`, `sort_order`, `status`, `created_at`) VALUES (1, 'main_complaints', 'প্রধান সমস্যা ও অভিযোগ', 'Main Complaints & Presenting Symptoms', 'রোগীর প্রাথমিক ও তাৎক্ষণিক সমস্যাসমূহের তালিকা।', 'Initial and immediate complaints reported by patient.', 2, 'active', '2026-11-19 08:30:40');
INSERT INTO `diagnosis_categories` (`id`, `code`, `name_bn`, `name_en`, `description_bn`, `description_en`, `sort_order`, `status`, `created_at`) VALUES (2, 'physical_symptoms', 'শারীরিক অসুস্থতা ও রোগের অস্বাভাবিকতা', 'Physical Symptoms & Health Complaints', 'বিভিন্ন শারীরিক অসুস্থতা, অনিয়ম, অব্যক্ত ব্যথা ও রোগের অস্বাভাবিক শারীরিক লক্ষণ।', 'Somatic issues, persistent pain unresponsive to standard treatments, and bodily complaints.', 3, 'active', '2026-11-19 08:30:40');
INSERT INTO `diagnosis_categories` (`id`, `code`, `name_bn`, `name_en`, `description_bn`, `description_en`, `sort_order`, `status`, `created_at`) VALUES (3, 'sleep_problems', 'ঘুমের সমস্যা', 'Sleep-Related Problems', 'অনিদ্রা, রাতে বারবার ঘুম ভেঙে যাওয়া ও ঘুমের ব্যাঘাত সংক্রান্ত সমস্যাসমূহ।', 'Insomnia, nocturnal restlessness, sleep paralysis, and waking disturbances.', 4, 'active', '2026-11-19 08:30:40');
INSERT INTO `diagnosis_categories` (`id`, `code`, `name_bn`, `name_en`, `description_bn`, `description_en`, `sort_order`, `status`, `created_at`) VALUES (4, 'dream_problems', 'স্বপ্নকেন্দ্রিক সমস্যা', 'Dream-Related Problems', 'ভীতিকর স্বপ্ন, আক্রমণ, সাপ, উঁচু থেকে পতন ও দুঃস্বপ্ন সংক্রান্ত লক্ষণসমূহ।', 'Recurrent disturbing dreams, animal attacks, falling sensations, and haunting visions.', 5, 'active', '2026-11-19 08:30:40');
INSERT INTO `diagnosis_categories` (`id`, `code`, `name_bn`, `name_en`, `description_bn`, `description_en`, `sort_order`, `status`, `created_at`) VALUES (5, 'rizq_obstacles', 'রিজিক, সফলতা ও নিয়ামতে প্রতিবন্ধকতা', 'Difficulties Related to Rizq, Success & Blessings', 'আয়-উপার্জনে বরকতের অভাব, চাকরি, ব্যবসা, বিয়ে ও পড়াশোনায় অযাচিত অচলাবস্থা সংক্রান্ত লক্ষণ।', 'Unexplained impediments in earnings, job prospects, trade transactions, and life milestones.', 6, 'active', '2026-11-19 08:30:40');
INSERT INTO `diagnosis_categories` (`id`, `code`, `name_bn`, `name_en`, `description_bn`, `description_en`, `sort_order`, `status`, `created_at`) VALUES (6, 'mental_behavioral', 'মানসিক, চারিত্রিক ও সম্পর্কগত পরিবর্তন', 'Mental, Behavioral & Relational Changes', 'মন-মেজাজের তীব্র পরিবর্তন, অহেতুক ক্রোধ, সন্দেহ, প্রিয়জনদের প্রতি বিদ্বেষ ও স্মৃতিভ্রম সংক্রান্ত লক্ষণ।', 'Psychological, behavioral, and relational shifts. Includes clinical safety monitoring.', 7, 'active', '2026-11-19 08:30:40');
INSERT INTO `diagnosis_categories` (`id`, `code`, `name_bn`, `name_en`, `description_bn`, `description_en`, `sort_order`, `status`, `created_at`) VALUES (7, 'worship_obstacles', 'ইবাদতে বাধা ও আধ্যাত্মিক অবনতি', 'Obstacles in Worship & Spiritual Decline', 'সালাত, কুরআন তিলাওয়াত, আযান ও যিকিরে অস্বস্তি এবং ফরজ ইবাদতে চরম অনিচ্ছা সংক্রান্ত লক্ষণসমূহ।', 'Difficulties initiating or sustaining prayer, recitation discomfort, and spiritual obstacles.', 8, 'active', '2026-11-19 08:30:40');
INSERT INTO `diagnosis_categories` (`id`, `code`, `name_bn`, `name_en`, `description_bn`, `description_en`, `sort_order`, `status`, `created_at`) VALUES (8, 'onset_history', 'সমস্যা শুরুর সময় ও পটভূমি', 'Problem Onset & Background History', 'সমস্যা শুরু হওয়ার সময়কাল, সূচনা, পূর্ববর্তী চিকিৎসা ও পটভূমি সংক্রান্ত কাঠামোবদ্ধ প্রশ্নাবলী।', 'Structured clinical history taking questions on problem onset, progression, and prior treatments.', 9, 'active', '2026-11-19 08:30:40');
INSERT INTO `diagnosis_categories` (`id`, `code`, `name_bn`, `name_en`, `description_bn`, `description_en`, `sort_order`, `status`, `created_at`) VALUES (9, 'family_social', 'পারিবারিক ও সামাজিক অবস্থা', 'Family & Social History', 'পারিবারিক পরিবেশ, পারস্পরিক সম্পর্ক, বংশগত ব্যাধি ও সামাজিক প্রেক্ষাপট সংক্রান্ত কাঠামোবদ্ধ প্রশ্নাবলী।', 'Structured assessment questions evaluating family dynamics, hereditary patterns, and domestic wellbeing.', 10, 'active', '2026-11-19 08:30:40');
INSERT INTO `diagnosis_categories` (`id`, `code`, `name_bn`, `name_en`, `description_bn`, `description_en`, `sort_order`, `status`, `created_at`) VALUES (10, 'patient_main_symptoms', 'রোগীর প্রধান উপসর্গসমূহ', 'Patient\'s Main Symptoms', 'রোগীর প্রধান প্রধান উপসর্গ ও অভিযোগসমূহ (ম্যানুয়াল বিবরণী)', 'Patient\'s primary presenting symptoms and complaints (manual entry)', 1, 'active', '2026-11-19 14:16:58');
