INSERT INTO `ruqyah_sessions` (`id`, `session_id`, `patient_id`, `appointment_id`, `session_number`, `session_date`, `raqi_name`, `initial_assessment`, `reported_symptoms`, `medical_history_checked`, `quranic_verses_recited`, `authentic_supplications`, `observed_reactions`, `raqi_observations`, `professional_assessment`, `assessment_category`, `prescribed_remedies`, `recommendations`, `next_followup_date`, `status`, `created_at`, `updated_at`, `manual_diagnosis`, `prescribed_amal`, `raqi_comments`, `special_advice`, `physical_observations`, `patient_main_symptoms`) VALUES (1, 'RS-1001-01', 'RSCC-P-1001', 'APT-20261118-001', 1, '2026-11-18', 'Muhammadullah Miah', 'Patient arrived alert but visibly anxious with tense shoulder posture.', 'Chest constriction, palpitation, recurring black dog nightmares.', 'Cardiology clearance verified, no cardiac abnormalities detected.', '["Surah Al-Fatihah (7 times)","Ayat al-Kursi (Al-Baqarah: 255)","Al-Baqarah: 102 (Verses of Sihr)","Al-Baqarah: 284-286","Al-A\'raf: 117-122 (Moses and Sorcerers)","Yunus: 81-82 (Nullification of magic)","Ta-Ha: 69","As-Saffat: 1-10","Al-Ikhlas, Al-Falaq, An-Nas (3 times each)"]', '["Adhhibil-ba\'sa Rabban-naas, ishfi wa Antash-Shaafee...","Bismillahi arqeeka, min kulli shay\'in yu\'dheeka...","A\'oodhu bi-kalimaatillaahit-taammaati min sharri maa khalaq...","Hasbiyallahu la ilaha illa Huwa, \'alayhi tawakkaltu..."]', '["Severe trembling in right arm and knee during recitation of Al-Baqarah 102","Deep repeated yawning during Mu\'awwidhatayn","Profuse cold sweating on forehead","Temporary nausea but no vomiting"]', 'Noticeable physical reaction to verses addressing Sihr and Hasad. Patient maintained consciousness throughout. Breathing stabilized immediately after recitation concluded with Duas.', 'Signs consistent with spiritual distress / suspected affliction with strong element of Hasad (Evil Eye) affecting livelihood and well-being. No psychosis observed. Patient responded positively to Prophetic supplications.', 'Spiritual Affliction Suspected (Hasad/Evil Eye)', '["Ruqyah-recited water: 1 glass to drink every morning on empty stomach","Ruqyah water bathing for 7 consecutive days (adding 7 crushed green Sidr leaves)","Olive oil recited upon: massage neck, chest and joints before sleeping","Pure Black Seed (Kalonji) oil: 5 drops with warm water daily","Strict adherence to Morning & Evening Adhkar (Hisnul Muslim)"]', 'Maintain 5 daily prayers in congregation at Masjid. Discontinue all un-Islamic amulets permanently. Perform Istighfar 100 times daily.', '2026-11-25', 'Completed', '2026-11-18 08:12:08', '2026-11-18 08:12:08', NULL, NULL, NULL, NULL, NULL, NULL);
