INSERT INTO `ruqyah_sessions` (`id`, `session_id`, `patient_id`, `appointment_id`, `session_number`, `session_date`, `raqi_name`, `initial_assessment`, `reported_symptoms`, `medical_history_checked`, `quranic_verses_recited`, `authentic_supplications`, `observed_reactions`, `raqi_observations`, `professional_assessment`, `assessment_category`, `prescribed_remedies`, `recommendations`, `next_followup_date`, `status`, `created_at`, `updated_at`, `manual_diagnosis`, `prescribed_amal`, `raqi_comments`, `special_advice`, `physical_observations`, `patient_main_symptoms`) VALUES (52, 'RS-P1001-02', 'RSCC-P-1001', NULL, 2, '2026-11-19', 'মুহাম্মদুল্লাহ মিয়া', NULL, 'দীর্ঘস্থায়ী তীব্র মাথাব্যথা, অনিদ্রা ও বুক ভারী লাগা', 'মস্তিষ্কের সিটি স্ক্যান ও ইসিজি রিপোর্ট স্বাভাবিক। কোনো শারীরিক রোগ ধরা পড়েনি।', NULL, NULL, '["Trembling / involuntary shivering in limbs","Sudden weeping / tears without grief","Deep repeated yawning"]', NULL, NULL, 'আইন (Ayn), সেহের (Sihr)', NULL, NULL, '2026-11-26', 'Completed', '2026-11-19 14:36:44', '2026-11-19 14:36:44', '["আইন (Ayn)","সেহের (Sihr)"]', 'সকালে খালি পেটে ১ গ্লাস পড়া পানি পান, রাতে জয়তুন তেল মালিশ এবং সকাল-সন্ধ্যার আজকার পাঠ।', 'রোগীর লক্ষণসমূহ সিহর ও বদনজরের সাথে সঙ্গতিপূর্ণ। রুকইয়াহ তিলাওয়াত চলাকালীন স্পষ্ট শারীরিক সংবেদনশীলতা পরিলক্ষিত হয়েছে।', 'পাঁচ ওয়াক্ত সালাত জামাতে আদায় করা এবং সব ধরনের তাবিয বর্জন করা।', 'তিলাওয়াত চলাকালীন রোগীর ডান হাত কাঁপছিল এবং প্রচণ্ড কান্নার ভাব হয়েছিল।', 'দীর্ঘস্থায়ী তীব্র মাথাব্যথা, অনিদ্রা ও বুক ভারী লাগা');
