INSERT INTO `reports` (`id`, `report_id`, `report_type`, `patient_id`, `session_id`, `title`, `generated_by`, `data_snapshot`, `created_at`) VALUES (335, 'RPT-SESS-RS-1001-01-5576', 'ruqyah_session', 'RSCC-P-1001', 'RS-1001-01', 'Ruqyah Session #1 Report - Tariqul Islam', 'Muhammadullah Miah', '{"session":{"id":1,"session_id":"RS-1001-01","patient_id":"RSCC-P-1001","appointment_id":"APT-20261118-001","session_number":1,"session_date":"2026-11-18","raqi_name":"Muhammadullah Miah","initial_assessment":"Patient arrived alert but visibly anxious with tense shoulder posture.","reported_symptoms":"Chest constriction, palpitation, recurring black dog nightmares.","medical_history_checked":"Cardiology clearance verified, no cardiac abnormalities detected.","quranic_verses_recited":"[\\"Surah Al-Fatihah (7 times)\\",\\"Ayat al-Kursi (Al-Baqarah: 255)\\",\\"Al-Baqarah: 102 (Verses of Sihr)\\",\\"Al-Baqarah: 284-286\\",\\"Al-A\'raf: 117-122 (Moses and Sorcerers)\\",\\"Yunus: 81-82 (Nullification of magic)\\",\\"Ta-Ha: 69\\",\\"As-Saffat: 1-10\\",\\"Al-Ikhlas, Al-Falaq, An-Nas (3 times each)\\"]","authentic_supplications":"[\\"Adhhibil-ba\'sa Rabban-naas, ishfi wa Antash-Shaafee...\\",\\"Bismillahi arqeeka, min kulli shay\'in yu\'dheeka...\\",\\"A\'oodhu bi-kalimaatillaahit-taammaati min sharri maa khalaq...\\",\\"Hasbiyallahu la ilaha illa Huwa, \'alayhi tawakkaltu...\\"]","observed_reactions":"[\\"Severe trembling in right arm and knee during recitation of Al-Baqarah 102\\",\\"Deep repeated yawning during Mu\'awwidhatayn\\",\\"Profuse cold sweating on forehead\\",\\"Temporary nausea but no vomiting\\"]","raqi_observations":"Noticeable physical reaction to verses addressing Sihr and Hasad. Patient maintained consciousness throughout. Breathing stabilized immediately after recitation concluded with Duas.","professional_assessment":"Signs consistent with spiritual distress / suspected affliction with strong element of Hasad (Evil Eye) affecting livelihood and well-being. No psychosis observed. Patient responded positively to Prophetic supplications.","assessment_category":"Spiritual Affliction Suspected (Hasad/Evil Eye)","prescribed_remedies":"[\\"Ruqyah-recited water: 1 glass to drink every morning on empty stomach\\",\\"Ruqyah water bathing for 7 consecutive days (adding 7 crushed green Sidr leaves)\\",\\"Olive oil recited upon: massage neck, chest and joints before sleeping\\",\\"Pure Black Seed (Kalonji) oil: 5 drops with warm water daily\\",\\"Strict adherence to Morning & Evening Adhkar (Hisnul Muslim)\\"]","recommendations":"Maintain 5 daily prayers in congregation at Masjid. Discontinue all un-Islamic amulets permanently. Perform Istighfar 100 times daily.","next_followup_date":"2026-11-25","status":"Completed","created_at":"2026-11-18 08:12:08","updated_at":"2026-11-18 08:12:08"},"patient":{"id":1,"patient_id":"RSCC-P-1001","full_name":"Tariqul Islam","phone":"01812345678","age":34,"gender":"Male","address":"Rampur, Feni Sadar, Feni","emergency_contact":"Brother: 01899887766","marital_status":"Married","registration_date":"2026-11-18 08:12:08","notes":"Complains of sudden severe chest tightness and recurring nightmares since past 6 months.","created_at":"2026-11-18 08:12:08","updated_at":"2026-11-18 08:12:08"}}', '2026-11-19 13:30:35');
